/**
 * Types for the JSON files generated by `scripts/extract-game-data.mjs`.
 *
 * Unit conventions (already normalised by the script):
 * - Solid amounts are in items; fluid/gas amounts are in m³ (the game stores them in litres).
 * - Durations are in seconds.
 * - Power is in MW.
 * - Energy is in MJ per item (solids) or MJ per m³ (fluids).
 */

export interface LocalizedText {
  es: string;
  en: string;
}

export type ItemForm = 'solid' | 'liquid' | 'gas';

export interface Item {
  /** Game class name, e.g. `Desc_IronPlate_C`. Used as the stable ID everywhere. */
  id: string;
  name: LocalizedText;
  description: LocalizedText;
  form: ItemForm;
  /** True for raw resources that are extracted from the world (ores, water, oil...). */
  isRawResource: boolean;
  /** Max items per inventory slot. `null` for fluids. */
  stackSize: number | null;
  /** AWESOME Sink points per item. */
  sinkPoints: number;
  /** Energy released when burnt in a generator (MJ/item or MJ/m³). 0 if not a fuel. */
  energyMJ: number;
  radioactiveDecay: number;
  /** Fluid colour as `#rrggbb`, `null` for solids. */
  fluidColor: string | null;
  /** Unreal texture path of the big icon, used later to map extracted icons. */
  iconPath: string | null;
}

export interface ItemAmount {
  item: string;
  amount: number;
}

export interface Recipe {
  /** Game class name, e.g. `Recipe_IronPlate_C`. */
  id: string;
  name: LocalizedText;
  /** True for alternate recipes (hard drive unlocks, or MAM ones named "Alternate: ..."). */
  alternate: boolean;
  ingredients: ItemAmount[];
  products: ItemAmount[];
  /** Seconds per cycle at 100% clock speed. */
  duration: number;
  /** Building ID that runs this recipe. */
  producedIn: string;
  /**
   * Only for buildings with variable power (Particle Accelerator, Converter, Quantum Encoder):
   * power oscillates between `min` and `max` MW during the cycle.
   */
  variablePower: { min: number; max: number } | null;
}

interface BuildingBase {
  /** Game class name, e.g. `Build_ConstructorMk1_C`. */
  id: string;
  name: LocalizedText;
  description: LocalizedText;
  /** Power consumption at 100% clock speed (MW). 0 for generators/variable power buildings. */
  powerMW: number;
  /** Exponent applied to clock speed when computing power: power = base * clock^exponent. */
  powerExponent: number;
  canOverclock: boolean;
}

export interface ManufacturerBuilding extends BuildingBase {
  kind: 'manufacturer';
  /** Somersloop slots. 0 means the building cannot be amplified. */
  somersloopSlots: number;
  /** Production bonus per somersloop (e.g. 0.5 for 2 slots: 2 × 0.5 = +100%). */
  somersloopMultiplier: number;
  /** Exponent applied to the production boost when computing power. */
  boostPowerExponent: number;
  /** Estimated power range for variable power buildings, `null` otherwise. */
  variablePower: { min: number; max: number } | null;
}

export interface ExtractorBuilding extends BuildingBase {
  kind: 'extractor';
  /** Seconds per extraction cycle. */
  cycleTime: number;
  /** Items (or m³) per cycle on a normal purity node. */
  itemsPerCycle: number;
  /** Convenience value: `itemsPerCycle / cycleTime * 60` (normal node, 100% clock). */
  ratePerMinute: number;
  allowedForms: ItemForm[];
  /** Allowed resources. Empty means "any raw resource of an allowed form". */
  allowedResources: string[];
}

export interface GeneratorFuel {
  fuel: string;
  /** Extra resource consumed alongside the fuel (e.g. water), `null` if none. */
  supplemental: string | null;
  byproduct: ItemAmount | null;
}

export interface GeneratorBuilding extends BuildingBase {
  kind: 'generator';
  /** Power produced at 100% clock speed (MW). */
  powerProductionMW: number;
  fuels: GeneratorFuel[];
  /**
   * Supplemental (water) consumption per MW. Water m³/min = powerProductionMW * ratio * 60 / 1000.
   */
  supplementalToPowerRatio: number;
  /** Geothermal only: power oscillates as `constant + factor * purity` over a cycle. */
  variablePowerProduction: { constant: number; factor: number; cycleLength: number } | null;
}

/** Resource Well Pressurizer: consumes power but does not extract by itself. */
export interface PressurizerBuilding extends BuildingBase {
  kind: 'pressurizer';
  allowedResources: string[];
}

export interface Transport {
  /** Game class name, e.g. `Build_ConveyorBeltMk1_C`. */
  id: string;
  kind: 'belt' | 'pipe';
  name: LocalizedText;
  tier: number;
  /** Max throughput: items/min for belts, m³/min for pipes. */
  ratePerMinute: number;
}

export type Building =
  ManufacturerBuilding | ExtractorBuilding | GeneratorBuilding | PressurizerBuilding;
